use xiom.io;

type Book = {
  title: Str;
  author: Str;
  pages: Int;
}

fn main() -> Int {
  let book1 = Book{ title: "The Giver", author: "Lois Lowry", pages: 240 };
  let book2 = Book{ title: "Holes", author: "Louis Sachar", pages: 233 };
  let book3 = Book{ title: "Wonder", author: "R.J. Palacio", pages: 320 };
  io.println(book1.title.to_str() + " — " + " pages");
  io.println(book1.pages.to_str());
  io.println(book2.title.to_str() + " — " + " pages");
  io.println(book2.pages.to_str());
  io.println(book3.title.to_str() + " — " + " pages");
  io.println(book3.pages.to_str());
  return 0;
}
